<style>
.iol-head{background:linear-gradient(135deg,#0d9488,#2563eb);color:#fff;border-radius:9px;padding:22px;margin-bottom:20px}.iol-panel{border-top:3px solid #0d9488}.eye-tabs,.formula-tabs{display:flex;gap:8px}.eye-tabs label,.formula-tabs label{margin:0;flex:1}.eye-tabs input,.formula-tabs input{display:none}.eye-tabs span,.formula-tabs span{display:block;text-align:center;border:1px solid #ddd;border-radius:5px;padding:10px;cursor:pointer}.eye-tabs input:checked+span,.formula-tabs input:checked+span{background:#0d9488;color:#fff;border-color:#0d9488}.result-main{text-align:center;background:linear-gradient(135deg,#ecfdf5,#eff6ff);padding:24px;border-radius:8px}.result-power{font-size:44px;color:#0f766e;font-weight:700}.option-grid,.target-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.option{border:1px solid #ddd;border-radius:6px;padding:10px;text-align:center}.option.recommended{border:2px solid #0d9488;background:#ecfdf5}.empty-result{text-align:center;color:#888;padding:70px 15px}
</style>
<div class="content-wrapper"><section class="content-header"><h1>IOL Power Calculator <small>Calculate intraocular lens power for cataract surgery</small></h1><ol class="breadcrumb"><li><a href="<?php echo site_url('admin/eyesurgery'); ?>"><i class="fa fa-arrow-left"></i> Back to Surgeries</a></li></ol></section><section class="content"><div class="iol-head"><h3 style="margin-top:0"><i class="fa fa-calculator"></i> IOL Power Calculator</h3><p style="margin:0">SRK/T, Haigis, Holladay 1 formulas for accurate lens power calculation</p></div><div class="row"><div class="col-md-6"><form id="iol-form"><?php echo $this->customlib->getCSRF(); ?><div class="box iol-panel"><div class="box-header with-border"><h3 class="box-title">Biometry Data</h3></div><div class="box-body">
<div class="form-group"><div class="eye-tabs"><label><input type="radio" name="eye" value="OD" checked><span>OD (Right Eye)</span></label><label><input type="radio" name="eye" value="OS"><span>OS (Left Eye)</span></label></div></div><div class="row"><div class="form-group col-sm-6"><label>Axial Length (mm)</label><input required type="number" min="15" max="40" step="0.01" class="form-control" name="axial_length" placeholder="e.g., 23.45"></div><div class="form-group col-sm-6"><label>Anterior Chamber Depth (mm)</label><input required type="number" min="1" max="8" step="0.01" class="form-control" name="acd" placeholder="e.g., 3.10"></div></div><div class="row"><div class="form-group col-sm-6"><label>K1 Flat (D)</label><input required type="number" min="25" max="65" step="0.01" class="form-control" name="k1" placeholder="e.g., 43.25"></div><div class="form-group col-sm-6"><label>K2 Steep (D)</label><input required type="number" min="25" max="65" step="0.01" class="form-control" name="k2" placeholder="e.g., 44.00"></div></div>
<div class="form-group"><label>IOL Model</label><select id="lens-model" class="form-control" name="lens_model"><option data-a="118.7">Alcon AcrySof IQ</option><option data-a="118.7">Alcon AcrySof SN60WF</option><option data-a="119.3">AMO Tecnis ZCB00</option><option data-a="119.1">Bausch+Lomb enVista</option><option data-a="118.8">Zeiss CT Lucia</option><option data-a="118.6">Rayner RayOne</option><option data-a="118">Custom</option></select></div><div class="row"><div class="form-group col-sm-6"><label>A-Constant</label><input required id="a-constant" type="number" step="0.1" class="form-control" name="a_constant" value="118.7"></div><div class="form-group col-sm-6"><label>Target Refraction (D)</label><input required type="number" step="0.25" class="form-control" name="target_refraction" value="0" placeholder="0 for emmetropia"></div></div>
<div class="form-group"><label>Formula</label><div class="formula-tabs"><label><input type="radio" name="formula" value="srkt" checked><span>SRK/T</span></label><label><input type="radio" name="formula" value="haigis"><span>Haigis</span></label><label><input type="radio" name="formula" value="holladay1"><span>Holladay 1</span></label></div></div><button class="btn btn-primary btn-block" id="calculate-btn" style="background:#0d9488;border-color:#0d9488"><i class="fa fa-calculator"></i> Calculate IOL Power</button><div id="iol-error" class="text-danger" style="margin-top:10px"></div></div></div></form></div>
<div class="col-md-6"><div class="box iol-panel"><div class="box-header with-border"><h3 class="box-title">Calculation Results</h3></div><div class="box-body" id="iol-results"><div class="empty-result"><i class="fa fa-calculator fa-4x"></i><h4>No Calculation Yet</h4><p>Enter biometry data and click calculate to see IOL power recommendations</p></div></div></div></div></div></section></div>
<script>
(function(){var form=document.getElementById('iol-form'),lens=document.getElementById('lens-model'),acon=document.getElementById('a-constant'),btn=document.getElementById('calculate-btn'),result=document.getElementById('iol-results'),error=document.getElementById('iol-error');lens.addEventListener('change',function(){acon.value=lens.options[lens.selectedIndex].getAttribute('data-a')});form.addEventListener('submit',function(e){e.preventDefault();error.textContent='';btn.disabled=true;btn.innerHTML='<i class="fa fa-spinner fa-spin"></i> Calculating...';var xhr=new XMLHttpRequest();xhr.open('POST','<?php echo site_url('admin/eyesurgery/iol_calculate'); ?>');xhr.setRequestHeader('X-Requested-With','XMLHttpRequest');xhr.onload=function(){btn.disabled=false;btn.innerHTML='<i class="fa fa-calculator"></i> Calculate IOL Power';var data;try{data=JSON.parse(xhr.responseText)}catch(ex){error.textContent='Calculation failed. Please try again.';return}if(!data.success){error.textContent=data.message;return}var options=data.options.map(function(o){return '<div class="option '+(o.power===data.power?'recommended':'')+'"><strong>'+Number(o.power).toFixed(2)+' D</strong><br><small>'+Number(o.refraction).toFixed(2)+' D</small></div>'}).join('');result.innerHTML='<div class="result-main"><small>Recommended IOL Power</small><div class="result-power">'+Number(data.power).toFixed(2)+'</div><strong>Diopters</strong><hr><small>Predicted Refraction</small><h4>'+Number(data.predicted_refraction).toFixed(2)+' D</h4></div><h4>Power Options</h4><div class="option-grid">'+options+'</div><h4>Target Recommendations</h4><div class="target-grid"><div class="option"><strong>Emmetropia</strong><br><small>0.00 D</small></div><div class="option"><strong>-0.5 Target</strong><br><small>Slight myopia</small></div><div class="option"><strong>Near Vision</strong><br><small>-1.50 D</small></div></div><h4>Calculation Parameters</h4><table class="table table-condensed"><tr><td>AL</td><td>'+form.axial_length.value+' mm</td></tr><tr><td>Avg K</td><td>'+Number(data.average_k).toFixed(2)+' D</td></tr><tr><td>A-Const</td><td>'+acon.value+'</td></tr></table>'};xhr.onerror=function(){btn.disabled=false;btn.textContent='Calculate IOL Power';error.textContent='Calculation failed. Please try again.'};xhr.send(new FormData(form))})})();
</script>
